import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String kind = sc.next();
        int n = sc.nextInt();
        double[] amounts = new double[n];
        for (int i = 0; i < n; i++) {
            amounts[i] = sc.nextDouble();
        }
        double tax = sc.nextDouble();
        Invoice inv;
        if (kind.equals("tax")) {
            TaxInvoice t = new TaxInvoice();
            t.items = amounts;
            t.taxPercent = tax;
            inv = t;
        } else {
            Invoice pl = new Invoice();
            pl.items = amounts;
            inv = pl;
        }
        System.out.printf("Subtotal: %.2f%n", inv.subtotal());
        System.out.printf("Grand total: %.2f%n", inv.total());
    }
}
class Invoice {
    double[] items;

    double subtotal() {
        double s = 0;
        for (double a : items) {
            s += a;
        }
        return s;
    }

    double total() {
        return subtotal();
    }
}

class TaxInvoice extends Invoice {
    double taxPercent;

    double total() {
        double base = super.total();
        return base + base * taxPercent / 100.0;
    }
}

